class Solution {
public:
    vector<int> timeTaken(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        auto get_w = [](int node) {
            return (node % 2 == 0) ? 2 : 1;
        };
        // dp[u] = {max1, node1, max2, node2}
        vector<array<int, 4>> dp(n, {0, -1, 0, -1});

        auto dfs1 = [&](auto& self, int u, int p) -> void {
            for (int v : adj[u]) {
                if (v == p) continue;
                self(self, v, u);
                int cand = dp[v][0] + get_w(v);
                if (cand > dp[u][0]) {
                    dp[u][2] = dp[u][0]; dp[u][3] = dp[u][1];
                    dp[u][0] = cand; dp[u][1] = v;
                } else if (cand > dp[u][2]) {
                    dp[u][2] = cand; dp[u][3] = v;
                }
            }
        };
        dfs1(dfs1, 0, -1);

        vector<int> ans(n, 0);
        auto dfs2 = [&](auto& self, int u, int p, int parent_cand) -> void {
            ans[u] = max(dp[u][0], parent_cand);
            for (int v : adj[u]) {
                if (v == p) continue;
                int other = (dp[u][1] == v) ? dp[u][2] : dp[u][0];
                int up_val = max(parent_cand, other) + get_w(u);
                self(self, v, u, up_val);
            }
        };
        dfs2(dfs2, 0, -1, 0);
        return ans;
    }
};

class Solution {
    public int[] timeTaken(int[][] edges) {
        int n = edges.length + 1;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; ++i) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int[][] dp = new int[n][4];
        dfs1(0, -1, adj, dp);
        int[] ans = new int[n];
        dfs2(0, -1, 0, adj, dp, ans);
        return ans;
    }

    private int getW(int node) {
        return (node % 2 == 0) ? 2 : 1;
    }

    private void dfs1(int u, int p, List<List<Integer>> adj, int[][] dp) {
        dp[u][1] = -1;
        dp[u][3] = -1;
        for (int v : adj.get(u)) {
            if (v == p) continue;
            dfs1(v, u, adj, dp);
            int cand = dp[v][0] + getW(v);
            if (cand > dp[u][0]) {
                dp[u][2] = dp[u][0]; dp[u][3] = dp[u][1];
                dp[u][0] = cand; dp[u][1] = v;
            } else if (cand > dp[u][2]) {
                dp[u][2] = cand; dp[u][3] = v;
            }
        }
    }

    private void dfs2(int u, int p, int parentCand, List<List<Integer>> adj, int[][] dp, int[] ans) {
        ans[u] = Math.max(dp[u][0], parentCand);
        for (int v : adj.get(u)) {
            if (v == p) continue;
            int other = (dp[u][1] == v) ? dp[u][2] : dp[u][0];
            int upVal = Math.max(parentCand, other) + getW(u);
            dfs2(v, u, upVal, adj, dp, ans);
        }
    }
}

var timeTaken = function(edges) {
    const n = edges.length + 1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const getW = (node) => (node % 2 === 0 ? 2 : 1);
    const dp = Array.from({ length: n }, () => [0, -1, 0, -1]);

    const dfs1 = (u, p) => {
        for (const v of adj[u]) {
            if (v === p) continue;
            dfs1(v, u);
            const cand = dp[v][0] + getW(v);
            if (cand > dp[u][0]) {
                dp[u][2] = dp[u][0]; dp[u][3] = dp[u][1];
                dp[u][0] = cand; dp[u][1] = v;
            } else if (cand > dp[u][2]) {
                dp[u][2] = cand; dp[u][3] = v;
            }
        }
    };
    dfs1(0, -1);

    const ans = new Array(n).fill(0);
    const dfs2 = (u, p, parentCand) => {
        ans[u] = Math.max(dp[u][0], parentCand);
        for (const v of adj[u]) {
            if (v === p) continue;
            const other = (dp[u][1] === v) ? dp[u][2] : dp[u][0];
            const upVal = Math.max(parentCand, other) + getW(u);
            dfs2(v, u, upVal);
        }
    };
    dfs2(0, -1, 0);
    return ans;
};
